# count known mismatches for transpose and reflected rows on test
trans_bad=[]
for r in range(30):
 for c in range(r+1,30):
  if grid[r][c]!=6 and grid[c][r]!=6 and grid[r][c]!=grid[c][r]: trans_bad.append((r,c,grid[r][c],grid[c][r]))
ref_bad=[]
for r in range(2,15):
 for c in range(30):
  if grid[r][c]!=6 and grid[31-r][c]!=6 and grid[r][c]!=grid[31-r][c]:ref_bad.append((r,c,grid[r][c],grid[31-r][c]))
len(trans_bad),trans_bad[:5],len(ref_bad),ref_bad[:5]

def orb(start):
 seen={start}; stack=[start]
 while stack:
  r,c=stack.pop()
  cand=[(c,r)]
  if 2<=r<=29: cand.append((31-r,c))
  if 2<=c<=29: cand.append((r,31-c))
  for p in cand:
   if 0<=p[0]<30 and 0<=p[1]<30 and p not in seen: seen.add(p);stack.append(p)
 return seen
all6=[(r,c) for r in range(30) for c in range(30) if grid[r][c]==6]
unresolved=[]; bad_orbits=[]
for p in all6:
 o=orb(p); vals={grid[r][c] for r,c in o if grid[r][c]!=6}
 if not vals: unresolved.append((p,len(o)))
 if len(vals)>1: bad_orbits.append((p,vals,[(q,grid[q[0]][q[1]]) for q in o if grid[q[0]][q[1]]!=6]))
len(all6),len(unresolved),unresolved[:10],len(bad_orbits),bad_orbits[:2]
